def validate(line):
    if "," not in line:
        raise ValueError("virgül eksik")
    name, age_text = line.split(",", 1)
    age_text = age_text.strip()
    if not age_text.isdigit():
        raise ValueError("yaş sayı değil")
    age = int(age_text)
    if age > 130:
        raise ValueError("yaş gerçekçi değil")
    return name.strip(), age

