def read_tasks(path):
    done, pending = [], []
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith("[x] "):
                done.append(line[4:])
            elif line.startswith("[ ] "):
                pending.append(line[4:])
    return done, pending

